vec3 Vignette(in vec3 rgb, in vec2 xyScreen)
{
    #define kVignetteStrength         1.             // The strength of the vignette effect
    #define kVignetteScale            0.6            // The scale of the vignette effect
    #define kVignetteExponent         2.5            // The rate of attenuation of the vignette effect

    vec2 uv = xyScreen / iResolution.xy;
    uv.x = (uv.x - 0.5) * (iResolution.x / iResolution.y) + 0.5;     

    float x = 2.0 * (uv.x - 0.5);
    float y = 2.0 * (uv.y - 0.5);

    float dist = sqrt(x*x + y*y) / kRoot2;

    float v = mix(1.0, max(0.0, 1.0 - pow(dist * kVignetteScale, kVignetteExponent)), kVignetteStrength);
    //return rgb * v;
    return pow(rgb, vec3(1. + (1. - v)));
}

vec3 ZoomBlur( in vec2 xyScreen, float blurMagnitude )
{
    if(kUseZoomBlur == 0)
    {
        vec4 texel = texelFetch(iChannel1, ivec2(xyScreen), 0);
        return texel.xyz / max(1., texel.w);
    }

    #define kMaxBlurSteps 20

    float d = length(xyScreen - iResolution.xy * 0.5) / iResolution.x;
    d = 1. - exp(-sqr(d * 3.));
    float gain = 1.;
    int kBlurSteps = int(float(kMaxBlurSteps) * d);
    float kBlurMag = blurMagnitude * d;

    if(kBlurSteps <= 1)
    {
        vec4 texel = texelFetch(iChannel1, ivec2(xyScreen), 0);
        return gain * texel.xyz / max(1., texel.w);
    }    

    vec2 uvScreen = xyScreen / iResolution.xy;

    vec3 sumWeights = kZero;
    vec3 sigma = vec3(0.);
    for(int idx = 0; idx < kBlurSteps; ++idx)
    {
        float xi = OrderedDither(ivec2(xyScreen));
        float t = (xi + float(idx)) / float(kBlurSteps);        
        vec2 uvSample = vec2(0.5) + (uvScreen - vec2(0.5)) * (1. + kBlurMag * mix(-0.5, 0.5, pow(t, 2.)));        

        vec4 texel = texture(iChannel1, uvSample, 0.);
        vec3 spectrum = mix(kOne, 2. * Hue(1. - float(idx) / float(kBlurSteps - 1)), d);
        sigma += spectrum * gain * (texel.xyz / max(1., texel.w));
        sumWeights += spectrum;
    }

    return sigma / sumWeights;
}

vec3 Metro(vec3 p)
{
    p = saturate(p);
    const float[30] c = float[30](
        -0.0180678482422229, 1.52889467695658, -0.0623136057660897, -0.155732388555471, -0.250867496990887, 0.0391384108545744, -0.00128400941904526, 
        -0.100944170159481, 0.0831639058413459, -0.0383214788806629, -0.185943804438669, 0.0970718501789022, 1.70442171194878, 0.394965137180801, 
        -0.0978565424331064, -0.827273202026112, -0.146243936353348, 0.130000627814526, 0.0780044400302885, -0.195279506849575, -0.189357731622912, 
        0.164477432439256, 0.475827161052928,1.79067080168516, -0.00482185897201533, -0.361898368087104,-0.688844153606519, -0.0102402980123174, 
        -0.0591881220813021,-0.11818940425772);

    vec3 f;
    for(int i = 0, j = 0; i < 3; ++i, j += 10)
    {
        f[i] = c[j] +
               p.x * (c[j+1] + p.x * c[j+4] + p.y * c[j+7] + p.z * c[j+9]) +
               p.y * (c[j+2] + p.y * c[j+5] + c[j+8]*p.z) +
               p.z * (c[j+3] + p.z * c[j+6]);
    }

    return saturate(f);
}


void mainImage( out vec4 rgba, in vec2 xyScreen )
{            
    float cameraShake = sqr(texelFetch(iChannel0, ivec2(0, kGlobalStateOffset), 0).x);

    if(kUseZoomBlur == 1)
    {    
        rgba.xyz = ZoomBlur(xyScreen, mix(0.05, 0.5, cameraShake));
    }
    else
    {
        rgba = texelFetch(iChannel1, ivec2(xyScreen), 0);
        rgba /= max(1., rgba.w);
    }    

    rgba.xyz = pow(rgba.xyz * 1.1, vec3(0.9));

    if(kUseVignette == 1)
    {
        rgba.xyz = Vignette(rgba.xyz, xyScreen);
    }

    if(kUseColourGrade == 1)
    {
        rgba.xyz = mix(rgba.xyz, applyColorGrade(rgba.xyz), 0.5);    
        //rgba.xyz = mix(rgba.xyz, pow(Metro(rgba.xyz), vec3(1.1)), 0.9);
    }    

    if(kUseFilmGrain == 1)
    {
        //uvec4 ctx = PCGInitialise(HashOf(uint(xyScreen.x), uint(xyScreen.y), uint(iFrame)));
        //float noise = Rand4(ctx).x;
        vec3 noise = texture(iChannel3, vec2((ivec2(xyScreen) + ivec2(HashOf(uint(iFrame), 9872652u), HashOf(uint(iFrame), 8789735u))) % 256) / 256., 0.).xyz;
        rgba.xyz *= 1. + 0.15 * mix(vec3(-1.), vec3(1.), noise);
    }

    if(kVisualiseDepthMap == 1)
    {
        rgba.xyz = Hue((unpackHalf2x16(floatBitsToUint(texelFetch(iChannel2, ivec2(xyScreen), 0).w)).x - 0.4) * 2.);         
    }
}

// PHYSICS AND GLOBAL STATE

void mainImage( out vec4 rgba, in vec2 xyScreen )
{    
    #define kInitSeed 3

    // The speed of the sim
    #define kSimSpeed 0.5

    //#define kUseHightmapTexture
    #define kUseCollisions

    // Update the global state used to determine the camera shake effects
    if(int(xyScreen.y) == kGlobalStateOffset && int(xyScreen.x) == 0)
    {
        rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);        
        float maxImpact = 0.;
        for(int ballIdx = 0; ballIdx < kNumBalls; ++ballIdx)
        {
            uint count = Uvec2FromFloat(texelFetch(iChannel0, ivec2(kSlotsPerBall*ballIdx+1, kBallStatesOffset), 0).w).x;
            vec4 state = texelFetch(iChannel0, ivec2(kSlotsPerBall*ballIdx+2, kBallStatesOffset), 0);   
            float impact = pow(saturate(1. - float(count) / kShakeDuration) * state.x, 2.) * mix(1., 0.5, state.z);

            if(impact > maxImpact)
            {
                rgba.x = impact;
                maxImpact = impact;                
            }
        }
        return;
    }

    // Update the ball states
    if(int(xyScreen.y) == kBallStatesOffset && int(xyScreen.x) < kNumBalls*kSlotsPerBall)
    {
        int ballIdx = int(xyScreen.x) / kSlotsPerBall;
        int slotIdx = int(xyScreen.x) % kSlotsPerBall;

        vec4[kSlotsPerBall] state;
        for(int i = 0; i < kSlotsPerBall; ++i)
        {
            state[i] = texelFetch(iChannel0, ivec2(kSlotsPerBall*ballIdx+i, kBallStatesOffset), 0);
        }
        #define p0 state[0]
        #define v0 state[1]
        #define s0 state[2]
        #define q0 state[3]
        uvec2 counters = Uvec2FromFloat(v0.w);
        float alpha = float(1 + ballIdx) / float(1 + kNumBalls);

        // Pick a coherent orbit to reduce excessive collisions
        float frameTime = float(iFrame) / kTargetFPS;
        float time = frameTime * kSimSpeed;
        float direction = float(2 * (ballIdx % 2) - 1);
        float phi = kTwoPi * (alpha + 0.1 * time * direction);
        float r = kTargetMajorRadius * sqrt(alpha);
        vec2 targetPosT = vec2(0.5) + vec2(cos(phi), sin(phi)) * r;

        // Add some random variation so make things more interesting
        time = frameTime * kSimSpeed * 0.25;
        RNGCtx rng = PCGInitialise(HashOf(uint(time), uint(ballIdx), uint(kInitSeed)));
        vec2 targetPos0 = Rand4(rng).xy;
        rng = PCGInitialise(HashOf(uint(time) + 1u, uint(ballIdx), uint(kInitSeed)));
        vec2 targetPos1 = Rand4(rng).xy;  
        vec2 targetPosS = mix(targetPos0, targetPos1, smoothstep(0., 1., fract(time)));

        targetPosT += vec2(cos(kTwoPi * targetPosS.x), sin(kTwoPi * targetPosS.x)) * mix(-0.5, 1., targetPosS.y) * kTargetMinorRadius;

        // If the ball was destroyed or we're initialising, reset the positions
        if(frameTime - xyScreen.x * kBallDropDelay <= 0. || s0.w < -(kBallRespawnDelay + kBallDropDelay * xyScreen.x)) 
        { 
            p0.xz = targetPosT;
            p0.y = 0.35;
            //p0.w = mix(0.5, 1.5, alpha) * kBallRadius;
            p0.w = kBallRadius;
            v0 *= 0.;  
            s0 = vec4(0., 0., 1., 1.);
            q0 = normalize(vec4(1., 0., 0., 0.));
        }        

        // If the ball is roughly on the heightfield and it's not been destroyed...
        if(IsOnPlane(p0) && IsAlive(s0))
        {
            for(int idx = 0; idx < kNumBalls; ++idx)
            {            
                vec4 sK = texelFetch(iChannel0, ivec2(idx*kSlotsPerBall+2, kBallStatesOffset), 0);
                vec4 pK = texelFetch(iChannel0, ivec2(idx*kSlotsPerBall, kBallStatesOffset), 0);

                // If another ball has detonated, extert a blast force on this one
                if(!IsAlive(sK) && sK.w > 0.)
                {
                    vec2 blastDir = pK.xz - p0.xz;
                    float len = length(blastDir);
                    v0.xz -= kBlastDeflection * sK.w / (1. + sqr(len * kBlastDeflectionFalloff)) * blastDir / len;
                }

                // A ball can't collide with itself
                if(idx != ballIdx && IsAlive(sK))
                {
                    vec4 vK = texelFetch(iChannel0, ivec2(idx*kSlotsPerBall+1, kBallStatesOffset), 0);

                    // If the balls intersect on another...
                    if(IsOnPlane(pK) && length2(pK.xz - p0.xz) < sqr(p0.w + pK.w))
                    {     
                        // Mean position and velocity for localisation
                        vec2 oP = (p0.xz + pK.xz) * 0.5;
                        vec2 oV = (v0.xz + vK.xz) * 0.5;

                        // Transform into the reference frame of the collision
                        mat2 basis;
                        basis[0] = normalize(pK.xz - p0.xz);
                        basis[1] = vec2(basis[0].y, -basis[0].x);
                        vec2 p0C = (p0.xz - oP) * basis;
                        vec2 v0C = (v0.xz - oV) * basis;
                        vec2 pKC = (pK.xz - oP) * basis;
                        vec2 vKC = (vK.xz - oV) * basis;

                        // Determine the normalised collision velocity we need to determine magnitude of the shockwave, camera shake, etc.
                        s0.x = saturate(mix(-kCollisionDeadZone, 1., (v0C.x - vKC.x) / kMaxShockSpeed)); 

                        // If the speed of collision exceeds the detonation threshold, mark the ball as dead and set its alpha to 1
                        if((v0C.x - vKC.x) / kBallMaxSpeed > kDetonationThreshold) 
                        { 
                            s0.x = 1.; // Detonated balls always go off with maximum power!
                            s0.z = 0.;
                            s0.w = 1.; 
                        }

                        // Transfer and conserve momentum
                        float meanMo = sqr(p0.w) * v0C.x + sqr(pK.w) * vKC.x;
                        v0C.x = -v0C.x * kBallElasticity + meanMo / (sqr(p0.w) + sqr(pK.w));                    

                        // Reset collision position so the balls no longer overlap
                        p0C.x = -p0.w * 1.01;

                        // Transform back into world space
                        p0.xz = (basis * p0C) + oP;
                        v0.xz = (basis * v0C) + oV;

                        // When two balls collide, the one with the lower rank stops chasing its target for a few seconds to let the other one pass
                        if(float(counters.x) > kShockwaveDuration * 0.1)
                        {
                            counters.x = 0u;

                            // Determine the rank of the ball and reset its counter. Alternate prioritising ranks on each frame
                            // to prevent low-rank balls consistently being stalled out
                            if(((iFrame & 1) == 0 && idx < ballIdx) || ((iFrame & 1) == 1 && idx > ballIdx))
                            {
                                counters.y = 0u;
                            }
                        }
                    } 
                }
            }
        }

        if(IsAlive(s0))
        {      
            // Chase after the target postion        
            v0.xz += (targetPosT - p0.xz) * kBallTargetAttraction * sqr(min(1., float(counters.y) / kBallCollisionChaseDelay)); 

            // Clamp the ball to the maximum speed if it exceeds it
            float len = length(v0.xz);
            if(len > kBallMaxSpeed) { v0.xz = (v0.xz / len) * kBallMaxSpeed; }

            // Apply friction
            v0.xz *= 1. - kBallFriction;

            // Apply gravity
            v0.y -= kGravityAccel * kSimSpeed;

            // Apply velocity to position of the ball
            p0.xyz += v0.xyz; 

            // Transform the orientation quaternion based upon the velocity in the y-plane
            vec4 roll = AxisAngleToQuat(SafeNormalise(vec3(-v0.z, 0., v0.x)), length(v0.xz) / p0.w);
            q0 = normalize(QuatMul(roll, q0));

            // Bounce when we hit the ground plane
            if(p0.y < 0.) { v0.y *= -kHFElasticity; p0.y = 1e-5; }    
        }

        // If the ball got knocked off the plane, kill and reset it
        if(v0.x < -0.5 || v0.x > 0.5 || v0.z < -0.5 || v0.z > 0.5)
        {
            s0.z = 0.;
            s0.w = -kFltMax;
        }

        counters = min(uvec2(0xffffu), counters + 1u);

#ifndef kUseCollisions
        p0.xz = targetPosT;
#endif

        v0.w = FloatFromUvec2(counters); // Pack counter values

        // Handle ball state
        s0.y = s0.x * max(0., 1. - float(counters.x) / 60.); // Collision force used by the renderer to make balls glow
        if(s0.z == 0.)
        {
            s0.w -= 1. / 60.;
        }

        rgba = state[slotIdx];
        return;

        #undef p0
        #undef v0
        #undef s0
    }

    if(int(xyScreen.x) >= kHeightFieldSize || int(xyScreen.y) >= kHeightFieldSize) { rgba *= 0.; return; }

    vec2 uvView = xyScreen / float(kHeightFieldSize - 1);

    /*rgba.xyz *= 0.;
    for(int i = 0; i < kNumBalls; ++i)
    {
        vec4 state = texelFetch(iChannel0, ivec2(i*2, kHeightFieldSize), 0);
        rgba.xyz = max(rgba.xyz, kGreen * float(length(state.xz - uvView) < state.w));
    }    
    return;*/

    // Diffuse the field
    float f = 0.;
    float sumWeights = 0.;
    int kernelRadius = int(ceil(kHFDiffusionRadius));
    for(int j = -kernelRadius; j <= kernelRadius; ++j)
    {
        for(int i = -kernelRadius; i <= kernelRadius; ++i)
        {
           if(int(xyScreen.x) + i >= 0 && int(xyScreen.x) + i < kHeightFieldSize && int(xyScreen.y) + j >= kHeightFieldOffset && int(xyScreen.y) + j < kHeightFieldOffset + kHeightFieldSize)
           {
               float w = 1. - sqrt(float(i*i) + float(j*j)) / (1. + kHFDiffusionRadius);
               if(w > 0.)
               {
                   f += texelFetch(iChannel0, ivec2(xyScreen) + ivec2(i, j), 0).x * w;
                   sumWeights += w;
               }
           }
        }
    }
    f /= sumWeights;

   // Attenuate the field
   f *= pow(mix(0.999, 1. - kHFViscoelasticity, f), 1. / kSimSpeed);
   rgba.x = f;

   // Calculate the impression of each ball on the heightmap
   float visibility = 1. - sqr(f);
   float shockwave = 0.;
   float bowWave = 0.;
   for(int i = 0; i < kNumBalls; ++i)
   {
        vec4 pState = texelFetch(iChannel0, ivec2(i*kSlotsPerBall+2, kBallStatesOffset), 0);        
        vec4 pPos = texelFetch(iChannel0, ivec2(i*kSlotsPerBall, kBallStatesOffset), 0);
        vec4 pVel = texelFetch(iChannel0, ivec2(i*kSlotsPerBall+1, kBallStatesOffset), 0);   
        uvec2 counters = Uvec2FromFloat(pVel.w);

        // Colllisions between balls create shockwaves that propagate outwards and dissipate over time
        float mag = min(1., float(counters.x) / kShockwaveDuration);
        shockwave += pState.x * mix(2., 1., pState.z) * exp(-sqr(50. * (length(uvView - pPos.xz) - 1.5 * mag - 0.02))) * pow(1. - mag, 10.0);

        if(pState.w <= 0.) { continue; }                

        float radius = pPos.w;
        float normSpeed = saturate(length(pVel.xz) / kBallMaxSpeed);

        if(pPos.y > radius) { continue; }

        vec2 dir = pVel.xz;
        vec2 uvLocal = uvView - pPos.xz;    
        float len = length(uvLocal);
        float d = saturate(len - radius * kHFBallInfluenceBias);
        float alpha = saturate(pState.w);

        // Make the gradient of the hightfield steeper in the direction of travel
        float dp = sqr(0.5 * dot(SafeNormalise(dir), uvLocal / len) + 0.5);
        float impact = mix(kDetonationCrater, 1.,  pState.z) * kHFBallInfluence * mix(1., mix(1., 0.5, normSpeed), dp);

        float fK = mix(1. + kDetonationCrater, 1., pState.z) * pow(exp(-sqr(d / impact)), 2.) * alpha;
        f = max(f, fK);

        // Each ball creates a bow wave when travelling quickly as the field piles up in front of it.
        if(IsAlive(pState))
        {
            bowWave = min(bowWave, kHFBowWaveMagnitude * normSpeed * kHFRange.x * exp(-sqr((len - radius * 1.5) * 50.)) * dp);
        }

        // Use the heightfield to create a fake ambient term 
        visibility *= (1. - sqrt(alpha) * pow(exp(-sqr(max(0., d - radius * kHFBallInfluenceBias) * 30.)), 0.5) * saturate(rgba.x - 0.)) * (1. - pPos.y);
    }

    float tex = 0.;
#ifdef kUseHightmapTexture
    tex = Sigmoid(texture(iChannel1, fract(uvView * 1.5 - 0.5), 0.).x - 0.2, 5.) * 0.2;
#endif

    // The persistent evaluation of the heightfield that's updated between frames
    rgba.x = mix(rgba.x, clamp(f, kHFRange.x, kHFRange.y), kHFReactiveness);
    // The visibility term
    rgba.y = pow(visibility * (1. - tex), 3.);
    // The shockwaves for each ball
    rgba.z = shockwave * kHFShockwaveBrightness;
    // The sum of the persistent and transient functions that's ultimately used to render the heightfield
    rgba.w = clamp(rgba.x + bowWave + shockwave * kHFShockwaveMagnitude + tex, kHFRange.x, kHFRange.y);
}

// RENDER

// Ray-sphere intersection test
bool RaySphere(inout Ray ray, inout HitCtx hit, in Transform transform)
{
    RayBasic localRay = RayToObjectSpace(ray.od, transform);

    // A ray intersects a sphere in at most two places which means we can find t by solving a quadratic
    float a = dot(localRay.d, localRay.d);
    float b = 2.0 * dot(localRay.d, localRay.o);
    float c = dot(localRay.o, localRay.o) - 1.0;

    float t0, t1;
    if(!QuadraticSolve(a, b, c, t0, t1)) { return false; }

    sort(t0, t1);   

    vec3 n;
    float tNear = ray.tNear;
    if(t0 > 0.0 && t0 < tNear) { tNear = t0; }
    else if(t1 > 0.0 && t1 < tNear) { tNear = t1; }
    else { return false; }

    ray.tNear = tNear;
    hit.n = PointAt(localRay, tNear);
    hit.uv = vec2(atan(hit.n.y, hit.n.x) / kTwoPi + 0.5, acos(clamp(hit.n.z, -1., 1.)) / kPi);
    hit.n = transpose(transform.rot) * hit.n;
    SetRayFlag(ray, kFlagsBackfacing, dot(localRay.o, localRay.o) < 1.0);

    return true;
}

bool RayBoundingBox(inout RayBasic localRay, out vec2 tNearFar, in vec3 lowerBound, vec3 upperBound)
{   
    vec3 tNearPlane, tFarPlane;
    for(int dim = 0; dim < 3; dim++)
    {
        if(abs(localRay.d[dim]) > 1e-10)
        {
            float t0 = (upperBound[dim] - localRay.o[dim]) / localRay.d[dim];
            float t1 = (lowerBound[dim] - localRay.o[dim]) / localRay.d[dim];
            if(t0 < t1) { tNearPlane[dim] = t0;  tFarPlane[dim] = t1; }
            else { tNearPlane[dim] = t1;  tFarPlane[dim] = t0; }
        }
    }    

    float tNearMax = cwiseMax(tNearPlane);
    float tFarMin = cwiseMin(tFarPlane);
    if(tNearMax > tFarMin) { return false; }  // Ray didn't hit the box

    tNearFar = vec2(tNearMax, tFarMin);
    return true;
}

bool RayHeightfield(inout Ray ray, inout HitCtx hit, in Transform transform, out float occlusion, inout vec3 L)
{
    RayBasic localRay = RayToObjectSpace(ray.od, transform);
    float localMag = length(localRay.d);
    localRay.d /= localMag;     

    vec2 tNearFar;
    if(!RayBoundingBox(localRay, tNearFar, kHFBBoxLower, kHFBBoxUpper)) { return false; }

    float t = max(0., tNearFar.x ); 
    float dt = kHFInitStepSize;
    float zLast, fLast;
    int iterIdx;
    vec3 p;
    for(iterIdx = 0; iterIdx < kHFMaxIters; ++iterIdx)
    {         
        if(t > tNearFar.y) { return false; }

        p = PointAt(localRay, t);
        float f = TapHeightfield(iChannel0, p.xy, iResolution.xy).x;
        float z = p.z - mix(kHFBBoxLower.z, kHFBBoxUpper.z, f);

        if(z > 0. && z < kHFCutoffThreshold) { break; }

        if(iterIdx != 0)
        {
            if(sign(z) != sign(zLast)) { dt *= -0.5; }
        }

        fLast = f;
        zLast = z;
        t += dt;

        //L = kOne * sin01(fLast * 100.);
    }    

    //if(iterIdx == kHFMaxIters) {  L = kYellow; return false; }

    #define kHFDeltaNorm float(2. / float(kHeightFieldSize))
    float fx0 = TapHeightfield(iChannel0, p.xy + vec2(-1., 0.) * 0.5 * kHFDeltaNorm, iResolution.xy).x;
    float fx1 = TapHeightfield(iChannel0, p.xy + vec2(1., 0.) * 0.5 *  kHFDeltaNorm, iResolution.xy).x;
    float fy0 = TapHeightfield(iChannel0, p.xy + vec2(0., -1.) * 0.5 * kHFDeltaNorm, iResolution.xy).x;
    float fy1 = TapHeightfield(iChannel0, p.xy + vec2(0., 1.) * 0.5 *  kHFDeltaNorm, iResolution.xy).x;
    vec2 n2 = kHFHeight * -vec2(fx1 - fx0, fy1 - fy0) / kHFDeltaNorm;
    //n2 = atan(n2) / kHalfPi;    
    n2 = sign(n2) * (1. - 1. / sqrt(1. + n2*n2));
    vec3 n = vec3(n2, sqrt(1. - sqr(n2.x) - sqr(n2.y)));

    ray.tNear = t / localMag;
    hit.n = transpose(transform.rot) * n;
    hit.kickoff = 1e-3;
    occlusion = TapHeightfield(iChannel0, p.xy, iResolution.xy).y;
    return true;
}

Ray CreatePinholeCameraRay(vec2 uvScreen, vec3 cameraPos, vec3 cameraLookAt, vec3 cameraUp, float fov)
{   
    Ray ray;
    ray.od.o = cameraPos;
    ray.od.d = transpose(CreateBasis(normalize(cameraPos - cameraLookAt), cameraUp)) * normalize(vec3(uvScreen, -1. / tan(toRad(fov))));
    ray.tNear = kFltMax;
    ray.weight = vec3(1.0, 1.0, 1.0);
    ray.flags = kFlagsCausticPath;
    ray.depth = 0;

    return ray;  
}

// Peturb the normal using the tangent space in the hit context
vec3 PerturbNormal(inout HitCtx hit, sampler2D sampler, float alpha, float delta)
{
    alpha = sign(alpha) * sqr(alpha);

    float dpdu = luminance(texture(sampler, hit.uv + vec2(-delta, 0.), 0.).xyz - texture(sampler, hit.uv + vec2(delta, 0.), 0.).xyz) / (2. * delta);
    float dpdv = luminance(texture(sampler, hit.uv + vec2(0., -delta), 0.).xyz - texture(sampler, hit.uv + vec2(0., delta), 0.).xyz) / (2. * delta);

    return normalize(hit.n + (hit.tangent * dpdu + hit.cotangent * dpdv) * alpha);    
}

// Evaluates the texture using a triplanar mapping
vec3 Triplanar(vec3 p, vec3 n, float scale, int type, sampler2D sampler)
{
    p *= scale;
    vec3 rgbX = texture(sampler, mod(abs(p.yz), vec2(1.)), 0.).xyz;
    vec3 rgbY = texture(sampler, mod(abs(p.xz), vec2(1.)), 0.).xyz;
    vec3 rgbZ = texture(sampler, mod(abs(p.xy), vec2(1.)), 0.).xyz;

    vec3 w = pow(abs(n), vec3(2.));
    w /= sum(w);    

    if(type == 0)
    {
        return (rgbX * w.x + rgbY * w.y + rgbZ * w.z);
    }
    else
    {    
        float L = sin01(kTwoPi * 2. * luminance(rgbX * w.x + rgbY * w.y + rgbZ * w.z));
        return kOne * L / (1. + exp(-8. * mix(-1., 1., L)));
    }
}

// Perturbs the surface normal using a triplanar texture
vec3 PerturbNormalTriplanar(vec3 p, inout HitCtx hit, float alpha, float delta, float scale, int type, sampler2D sampler)
{    
    alpha = sign(alpha) * sqr(alpha);
    delta /= scale;

    mat3 basis = CreateBasis(hit.n);
    float dpdu = luminance(Triplanar(p + basis[0] * -delta, hit.n, scale, type, sampler) - 
                           Triplanar(p + basis[0] * delta, hit.n, scale, type, sampler)) / (2. * delta);
    float dpdv = luminance(Triplanar(p + basis[1] * -delta, hit.n, scale, type, sampler) - 
                           Triplanar(p + basis[1] * delta, hit.n, scale, type, sampler)) / (2. * delta);

    return normalize(hit.n + (basis[0] * dpdu + basis[1] * dpdv) * alpha);    
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    #define kHFScale 1.

    uint hash = HashOf(uint(xyScreen.x), uint(xyScreen.y), uint(iFrame));
    RNGCtx rng;
    vec4 xi;

    rgba *= 0.;
    rgba.xyz = kOne;
    vec2 uvView = ScreenToNormalisedScreen(xyScreen, iResolution.xy);    

    //#define kCameraPos vec3(0., 1., 1.) * 0.7
    #define kCameraLookAt vec3(0., -0.05, 0.)
    #define kCameraUp vec3(0., 1., 0)

    vec4[kNumBalls] pPos;
    vec4[kNumBalls] pVel;
    vec4[kNumBalls] pState;
    vec4[kNumBalls] pRot;
    //uint minCounter = 0xffffu;
    for(int i = 0; i < kNumBalls; ++i)
    {
        pPos[i] = texelFetch(iChannel0, ivec2(i*kSlotsPerBall, kBallStatesOffset), 0);
        pVel[i] = texelFetch(iChannel0, ivec2(i*kSlotsPerBall+1, kBallStatesOffset), 0);
        pState[i] = texelFetch(iChannel0, ivec2(i*kSlotsPerBall+2, kBallStatesOffset), 0);
        pRot[i] = texelFetch(iChannel0, ivec2(i*kSlotsPerBall+3, kBallStatesOffset), 0);
        //minCounter = min(minCounter, Uvec2FromFloat(pVel[i].w).x);
    }

    float camShake = pow(texelFetch(iChannel0, ivec2(0, kGlobalStateOffset), 0).x, 3.);

    //float shakeTime = iTime / (iTimeDelta * 2.);
    rng = PCGInitialise(hash);
    xi.x = HaltonBase2(hash + uint(iFrame));
    //float xi = OrderedDither(ivec2(xyScreen));
    float shakeTime = ((xi.x + float(iFrame)) / kTargetFPS) * 0.5 * kTargetFPS;
    vec3[2] shakeV;
    for(int i = 0; i < 2; ++i)
    {
        rng = PCGInitialise(HashOf(uint(shakeTime) + uint(i)));
        shakeV[i] = kCameraShake * (Rand4(rng).xyz * 2. - 1.);
    }

    rng = PCGInitialise(hash);

    xi = Rand4(rng);
    vec3 cameraLookAt = kCameraLookAt + camShake * (mix(shakeV[0], shakeV[1], smoothstep(0., 1., fract(shakeTime))/* + OrderedDither(ivec2(xyScreen)) * 0.1*/));    
    vec3 cameraPos = vec3(cos(-iTime * 0.05), 1., sin(iTime * 0.05)) * mix(0.4, 0.35, sin01(iTime * 0.11));

    vec3 cameraUp = kCameraUp;

    float cameraFoV = mix(35., 33., camShake * xi.y);
    Ray ray = CreatePinholeCameraRay(uvView, cameraPos, cameraLookAt, cameraUp, cameraFoV);    

    //rgba.w = uintBitsToFloat(packHalf2x16(vec2(100., 1.)));    

    vec3 L = kZero;
    HitCtx hit;  
    float tNearCam = kFltMax;
    for(int depth = 0; depth < 2; ++depth)
    {
        ray.tNear = kFltMax;
        int hitID = -1;
        vec3 incandescence = kZero;
        vec3 albedo = kOne; 
        float alpha = 1.;

        Transform transform = CompoundTransform(vec3(0., 0., 0.), vec3(-kHalfPi, 0., 0.), 1.);
        float visibility;
        if(RayHeightfield(ray, hit, transform, visibility, rgba.xyz)) { hitID = 0; }

        visibility = mix(visibility, 1., 0.3);

        for(int ballIdx = 0; ballIdx < kNumBalls; ++ballIdx)
        {
            //if(!IsAlive(pState[ballIdx])) { continue; }
            if((depth > 0 && !IsAlive(pState[ballIdx])) || pState[ballIdx].w <= 0.) { continue; }            

            vec3 pos = (pPos[ballIdx].xyz - vec3(1., pPos[ballIdx].w, 1.) * 0.5) * kHFScale + pVel[ballIdx].xyz * HaltonBase2(hash + uint(iFrame));            
            pos.y += mix(kHFBBoxLower.z, kHFBBoxUpper.z, TapHeightfield(iChannel0, pos.xz * vec2(1., -1.), iResolution.xy).x) + pPos[ballIdx].w * 1.;
                     //  kHFBBoxLower.z + pPos[ballIdx].w * 1.5;                        

            float radius =  pPos[ballIdx].w * mix(1., kFireballSize, sqr(1. - pState[ballIdx].w));
            transform = CompoundTransform(pos, pRot[ballIdx], radius);

            if(RaySphere(ray, hit, transform)) 
            {                 
                hitID = 1 + ballIdx; 
                alpha = saturate(pState[ballIdx].w);
                if(pState[ballIdx].y > 0.)
                {
                    vec3 colour = mix(kOne, Hue(pState[ballIdx].y * 2.), 0.8);
                    if(pState[ballIdx].z == 0.)
                    {
                        //float bubble = (1. - sqr(pow(dot(hit.n, -ray.od.d), 5.) * 2. - 1.));                        
                        float theta = acos(saturate(dot(hit.n, -ray.od.d))) / kHalfPi;
                        float shockBubble = exp(-sqr(3. * mix(-1., 1., theta)));
                        //float bubble = sin01(kTwoPi * sqrt(dot(hit.n, -ray.od.d)));
                        incandescence += kFireballBrightness * colour * shockBubble * pow(pState[ballIdx].y, 3.);
                    }
                    else
                    {
                        incandescence = kSubDetonationBrightness * vec3(0.5, 0.2, 1.0) * pow(pState[ballIdx].y, 3.);
                    }

                    albedo *= mix(kOne, colour * 5., pow(pState[ballIdx].y, 2.));
                }
            }
        }


        vec3 p = PointAt(ray.od, ray.tNear);
        float lightPhi = kTwoPi * iTime * 0.05;
        float lightTheta = kHalfPi * mix(0.6, 0.7, sin01(iTime * 0.1));
        vec3 lightLocal = normalize(vec3(cos(lightPhi) * sin(lightTheta), cos(lightTheta), sin(lightPhi) * sin(lightTheta) * 2.) - p);

        float dots = mix(0., 1., float(fract(length(p.xz) * 20.) < 0.1 && fract(40. * atan2(p.x, p.z) / kTwoPi) < 0.1));

        // Ray escaped, so sample the environment sphere and we're done        
        if(hitID == -1)
        {
            L += ray.weight * 10. * pow(saturate(luminance(texture(iChannel2, ray.od.d, -1.).xyz) - 0.1), 1.5);// * vec3(1., .1, .3);
            break;
        }        

        // Cache the camera ray hit distance
        if(tNearCam == kFltMax && alpha == 1.) { tNearCam = length(p - cameraPos); }

        if(kVisualiseHeighfield == 1) 
        { 
            if(hitID == 0)
                L = kOne * Sigmoid(sin01(kTwoPi * 200. * (p.y + 10.)), 10.); 
            break; 
        }  
        if(kVisualiseAO == 1)
        {
            L = kOne * saturate(dot(-ray.od.d, hit.n)) * visibility;
            break;
        }
        if(kDisableAllShading == 1)
        {
            L = hit.n * 0.5 + 0.5;
            break;
        }

        // Apply triplanar bump mapping
        if(kUseBump == 1 && hitID == 0)
        {
            hit.n = PerturbNormalTriplanar(p + 5.1, hit, 0.05, 1e-3, 3., 0, iChannel1);
        }

        vec3 LGGX = kOne * EvaluateMicrofacetReflectorGGX(-ray.od.d, lightLocal, hit.n, (hitID == 0) ? 0.15 : 0.5);
        if(hitID == 0) { LGGX *= vec3(1., 0.3, 1.) * 0.2; }

        vec3 LLambert = kOne * saturate(dot(lightLocal, hit.n));

         // Heightmap was hit
        if(hitID == 0)
        {
            if(dot(lightLocal, hit.n) > 0.)
            {                
                if(kUseTextureAlbedo == 1)
                {
                    albedo *= mix(1., 0.7, Sigmoid(Triplanar(p + 5.1, hit.n, 2., 0, iChannel3).x - 0., 5.));
                }

                // Big ripple waves
                albedo += exp(-sqr(10. * (length(p) - 1.5 * fract(iTime * 0.2) + 0.1)));
                // Ball ripples
                float shockwaves = TapHeightfield(iChannel0, p.xz * vec2(1., -1.), iResolution.xy).z;
                albedo += shockwaves;                

                // Irridescent diffuse effect
                float thetaI = saturate(dot(-ray.od.d, hit.n));
                float hue = mix(0.4, 1., pow(1.1 * thetaI, 2.5));
                hue += smoothstep(0., 1., saturate(shockwaves)) * 1.;
                vec3 colour = mix(kOne, Hue(hue), 0.6);      

                L += (LGGX + albedo * visibility * colour * LLambert * 2.) * ray.weight;

                // Dot pattern
                //L += kOne  * mix(0., 1., float(fract(length(p.xz) * 20.) < 0.1 && fract(40. * atan2(p.x, p.z) / kTwoPi) < 0.1));
            }    

            L += incandescence;
            break;
       }

       // Ball was hit
       else if(hitID >= 1)
       {           
           if(alpha == 1.)
           {           
               float stripes = mix(1., 0., Sigmoid(cos01(2. * kPi * (5. * hit.uv.y + hit.uv.x)), 5.));
               //float stripes = float(SDFLine(hit.uv, vec2(0.3, 0.5), vec2(0.7, 0.5), 0.25, 0.05));

               L += ray.weight * (LLambert * 0.2 + LGGX) * stripes;

               if(depth == 1)
               {
                    L += (1. - stripes) * ray.weight * albedo * 10. * pow(saturate(luminance(texture(iChannel2, reflect(ray.od.d, hit.n), -1.).xyz) - 0.1), 1.5);// * vec3(1., .1, .3);
               }
               else
               {
                   vec3 extant = reflect(ray.od.d, hit.n);
                   ray.weight *= (1. - stripes) * albedo * mix(1., FresnelApprox(saturate(-dot(ray.od.d, hit.n)), 1., 10.), 1.);
                   ray.od.o = p + hit.n * hit.kickoff;
                   ray.od.d = extant;                   
               }

                if(1. - stripes < 1e-6) { break; }
           }
           else
           {
               //ray.od.o = p - hit.n * hit.kickoff;
           }
           L += incandescence;
       }
   }


   rgba.xyz = L;
   rgba.w = uintBitsToFloat(packHalf2x16(vec2(tNearCam, 1.)));

}

// BLOOM FIRST PASS

void mainImage( out vec4 rgba, in vec2 xyScreen )
{    
    rgba *= 0.;

    if(kUseBloom == 1)
    {    
        vec3 L0 = SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution), vec2(0.05), vec3(1.5, 1.8, 2.4), iChannel0); 
        vec3 L1 = SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution), vec2(0.1), vec3(1.0, 1.8, 2.4), iChannel0); 

        rgba.x = uintBitsToFloat(_packHalf2x16(L0.xy));
        rgba.y = L0.z;
        rgba.z = uintBitsToFloat(_packHalf2x16(L1.xy));
        rgba.w = L1.z;
    }
}

// DOF BLUR AND BLOOM SECOND PASS

float FocalCurve(float depth, float focalPlane, float dof)
{
    return exp(-sqr(depth - focalPlane) / dof);

    //return float(abs(depth - focalPlane) < dof);
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{            
    #define kDOFBlurRadius 15.
    #define kDOFBlurKernel 3
    #define kDepthGamma 1.
    #define kDOFBlurGain float(kDOFBlurRadius) / float(kDOFBlurKernel)
    #define kDOFJitter 1.

    float focalPlane = 0.55;
    float fStop = 0.03;

    vec4 texel0 = texelFetch(iChannel1, ivec2(xyScreen), 0);
    //texel0 = TestMap(xy);     

    vec2 unpacked = unpackHalf2x16(floatBitsToUint(texel0.w));
    float depth0 = unpacked.x, alpha0 = unpacked.y;
    depth0 = pow(depth0, kDepthGamma);
    float focus0 = FocalCurve(depth0, focalPlane, fStop);

    texel0.xyz = saturate(texel0.xyz);

    vec3 sumL = kZero;

    if(kUseDoFBlur == 0)
    {
        sumL = texelFetch(iChannel1, ivec2(xyScreen), 0).xyz;
    }
    else
    {   

        float sumWeights = 0.0;
        float sumAlpha = 0.0;

        for(int v = -kDOFBlurKernel; v <= kDOFBlurKernel; ++v)
        {
            for(int u = -kDOFBlurKernel; u <= kDOFBlurKernel; ++u)
            {            
                vec2 uv = kDOFBlurGain * (vec2(u, v) + kDOFJitter * (texelFetch(iChannel2, (ivec2(xyScreen) + ivec2(u, v)) % 1024, 0).xy));
                ivec2 ij = ivec2(xyScreen) + ivec2(uv);

                if(ij.x < 0 || ij.x >= int(iResolution.x) || ij.y < 0 || ij.y >= int(iResolution.y)) { continue; }

                vec4 texelK = texelFetch(iChannel1, ij, 0);
                //texelK = TestMap(vec2(uv));            

                vec2 unpacked = unpackHalf2x16(floatBitsToUint(texelK.w));
                float depthK = unpacked.x, alphaK = unpacked.y;
                depthK = pow(depthK, kDepthGamma);
                float focusK = FocalCurve(depthK, focalPlane, fStop);

                if((u != 0 || v != 0) && alphaK != 0.0 && alphaK != 1.0) { continue; }            

                focusK = (depthK < depth0) ? focusK : max(focusK, focus0);

                //if(alpha0 != 0.0 && alpha0 != 1.0) { focusK = 0.0; }

                float weight = 0.0;
                float d = length(vec2(uv));
                float r = max(0., (float(kDOFBlurRadius) + 1.) * (1.0 - focusK));
                if(d < r)
                {
                    weight = 1. / (1.0 + (kPi * r*r));
                }            

                sumL += texelK.xyz * weight;
                sumAlpha += alphaK * weight;
                sumWeights += weight;
            }
        }    


        sumL /= max(1e-10, float(sumWeights));
        sumAlpha /= max(1e-10, float(sumWeights));


        if(sumWeights < 1e-2) sumL = texelFetch(iChannel1, ivec2(xyScreen), 0).xyz;

        if(sumAlpha > 0.0) { sumL /= sumAlpha; }
    }   

    if(kUseBloom == 1)
    {    
        vec3 bloom = SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution), vec2(0.5), vec3(1.5, 1.8, 2.4), 0, iChannel3) * 1.; 
        bloom += SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution), vec2(0.2), vec3(1.0, 1.8, 2.4), 1, iChannel3) * 1.;
        bloom *= 0.5;   
        sumL = mix(max(sumL, bloom), sumL + pow(max(kZero, bloom - kOne * 0.1), 1.7 * vec3(1., 1.1, 1.2)), 0.5);
    }

    // Accumulating like this gives a cheap form of anti-aliasing and motion blur
    rgba = texelFetch(iChannel0, ivec2(xyScreen), 0);
    rgba *= 0.6 * float(kUseAccumulationBlur);
    rgba.xyz += sumL;    
    rgba.w += 1.;


}

    // RENDER PARAMETERS

    #define kUseAccumulationBlur 1
    #define kUseDoFBlur 1
    #define kUseZoomBlur 1
    #define kUseBloom 1
    #define kUseVignette 1
    #define kUseColourGrade 1
    #define kUseFilmGrain 1
    #define kUseBump 1
    #define kUseTextureAlbedo 1

    #define kVisualiseDepthMap 0
    #define kVisualiseHeighfield 0
    #define kVisualiseAO 0
    #define kDisableAllFX 0
    #define kDisableAllShading 0

    // BALL DYNAMICS

    // Maximum number of balls on the field at any given time
    #define kNumBalls 12    
    // The radius of each ball
    #define kBallRadius 0.03    
    // The friction applied to each ball's motion on the heightfield
    #define kBallFriction 0.01    
    // The maximum speed of a ball
    #define kBallMaxSpeed 0.003    
    // The elasticity of the ball during collisions
    #define kBallElasticity .95         
    // The period of time a ball pauses after colliding with another ball
    #define kBallCollisionChaseDelay (60. * 5.)  
    // The attractive force that compells each ball to follow its target
    #define kBallTargetAttraction 0.001    
    // Acceleration due to gravity
    #define kGravityAccel .002    
    // The delay between consecutive balls dropping 
    #define kBallDropDelay 0.1    
    // The minimum delay between a ball detonating and it respawning
    #define kBallRespawnDelay 2.    
    // The extent to which the balls can travel as they follow their targets
    #define kTargetMajorRadius 0.3
    #define kTargetMinorRadius 0.15

    // DETONATIONS AND SHOCKWAVES

    // The size of the fireball created by each detonation
    #define kFireballSize 5.    
    // The peak intensity of the expanding fireball
    #define kFireballBrightness 50.    
    // The brightness of colliding balls which haven't yet detonated
    #define kSubDetonationBrightness 10.    
    // How much of a crator each detonation leaves behind
    #define kDetonationCrater 2.
    // The speed above which collision shockwaves can't get any bigger
    #define kMaxShockSpeed 0.002
    // The percentage of the maximum speed that causes a ball to detonate when it collides with another ball
    #define kDetonationThreshold .7
    // The duration of the shockwave
    #define kShockwaveDuration (60. * 5.)
    // How much the camera is shaken by an explosion 
    #define kCameraShake 0.1
    // The duration of the camera shake effect
    #define kShakeDuration (60. * 1.5)
    // The threshold below which collisions don't generate shockwaves
    #define kCollisionDeadZone 0.1
    // The degree to which a detonation deflects the balls around it
    #define kBlastDeflection 0.03
    // The rate at which the deflecting blastwave falls off
    #define kBlastDeflectionFalloff 200.       


    // HEIGHTFIELD PARAMETERS

    // How reactive the heightfield is to each ball
    #define kHFReactiveness 0.5
    // The elasticity of the hightfield (how much each ball bounces)
    #define kHFElasticity 0.6
    // The springiness of the heightfield
    #define kHFViscoelasticity 0.005
    // The size of the impact crater left by ball
    #define kHFBallInfluence 0.05
    // The margin as a function of radius around each ball to account for its volume
    #define kHFBallInfluenceBias 0.4 
    // The radius of the diffusion operation that causes the heightfield to return to its smooth state
    #define kHFDiffusionRadius 0.5
     // The magnitude of the shockwave on the heightfield
    #define kHFShockwaveMagnitude 0.5
    // The brightness of the shockwave on the material
    #define kHFShockwaveBrightness 1.    // How much of a bow wave is created as the balls move accross the heightfield
    #define kHFBowWaveMagnitude 1.

// INTERNAL PARAMETERS

    #define kHeightFieldSize 500
    #define kSlotsPerBall 4

    #define kBallStatesOffset 0
    #define kGlobalStateOffset 1
    #define kHeightFieldOffset 2

    #define kHFMaxIters 50
    #define kHFHeight 0.12
    #define kHFBBoxLower vec3(-0.5, -0.5, -kHFHeight * 0.5)
    #define kHFBBoxUpper vec3(0.5, 0.5, kHFHeight * 0.5)    
    #define kHFRange vec2(-0.5, 1.)
    #define kHFInitStepSize (2. * float(kHFHeight) / float(kHFMaxIters))
    #define kHFCutoffThreshold 1e-5

    #define kTargetFPS 60.

    #define IsAlive(state) (state.z != 0.)
    #define IsOnPlane(state) (state.y < state.w)   

#if kDisableAllFX == 1
    #undef kUseAccumulationBlur 
    #undef kUseDoFBlur 
    #undef kUseZoomBlur 
    #undef kUseBloom 
    #undef kUseVignette 
    #undef kUseColourGrade 
    #undef kUseFilmGrain 
    #undef kCameraShake
    #define kUseAccumulationBlur 0
    #define kUseDoFBlur 0
    #define kUseZoomBlur 0
    #define kUseBloom 0
    #define kUseVignette 0
    #define kUseColourGrade 0
    #define kUseFilmGrain 0
    #define kCameraShake 0.
#endif

