vec4 TapHeightfield(sampler2D sampler, vec2 p, vec2 res)
{
    p.y *= -1.;
    vec2 uv = saturate((p - kHFBBoxLower.xy) / (kHFBBoxUpper.xy - kHFBBoxLower.xy));
    vec4 texel = texture(sampler, (uv * float(kHeightFieldSize - 1) + vec2(0, kHeightFieldOffset)) / vec2(res), 0.);
    // Remap the range
    float f = mix(0.9, 0.1, (texel.w - kHFRange.x) / (kHFRange.y - kHFRange.x));
    return vec4(f, texel.yzw);
}

float atan2(float y, float x)
{
    float phi = atan(y, x);
    return (phi < 0.) ? (kTwoPi + phi) : phi;
}

float saw(float a)             
{ 
    a = mod(a / kPi, 2.);
    return (1. - (2. * abs(fract(a) - 0.5))) * -(floor(a) * 2. - 1.);
}

float cosaw(float a) { return saw(a + kHalfPi); }

float saw01(float a) { return saw(a) * 0.5 + 0.5; }
float cosaw01(float a) { return saw(a + kHalfPi) * 0.5 + 0.5; }

vec3 safeAtan(vec3 a, vec3 b)
{
    vec3 r;
    #define kAtanEpsilon 1e-10
    r.x = (abs(a.x) < kAtanEpsilon && abs(b.x) < kAtanEpsilon) ? 0.0 : atan(a.x, b.x); 
    r.y = (abs(a.y) < kAtanEpsilon && abs(b.y) < kAtanEpsilon) ? 0.0 : atan(a.y, b.y); 
    r.z = (abs(a.z) < kAtanEpsilon && abs(b.z) < kAtanEpsilon) ? 0.0 : atan(a.z, b.z); 
    return r;
}

vec3 SafeNormalise(vec3 v, vec3 n)
{
    float len = length(v);
    return (len > 1e-10) ? (v / len) : n;
}

vec2 SafeNormalise(vec2 v) { return v / (1e-10 + length(v)); }
