uint sobol(uint index, uint dim)
{
    uint X = 0u;
    for (uint bit = 0u; bit < 32u; ++bit)
    {
        uint mask = (index >> bit) & 1u;
        X ^= mask * directions[dim*32u+bit];
    }
    return X;
}

uint hash_combine(uint seed, uint v)
{
    return seed ^ (v + (seed << 6) + (seed >> 2));
}

uint laine_karras_permutation(uint x, uint seed)
{
    x += seed;
    x ^= x * 0x6c50b47cu;
    x ^= x * 0xb82f1e52u;
    x ^= x * 0xc7afe638u;
    x ^= x * 0x8d22f6e6u;
    return x;
}

uint nested_uniform_scramble_base2(uint x, uint seed)
{
    x = RadicalInverse(x);
    x = laine_karras_permutation(x, seed);
    x = RadicalInverse(x);
    return x;
}

float QRand(RNGCtx ctx, uint dim)
{
    uint seed = HashCombine(ctx.x, dim);

    return float(nested_uniform_scramble_base2(sobol(nested_uniform_scramble_base2(ctx.y, seed), 0u), hash_combine(seed, 0u))) / float(0xffffffffu);
}

vec4 QRand4(RNGCtx ctx, uint dim)
{
    vec4 xi;
    uint seed = HashCombine(ctx.x, dim);
    uint index = nested_uniform_scramble_base2(ctx.y, seed);
    for (uint d = 0u; d < 4u; ++d)
    {
        xi[d] = float(nested_uniform_scramble_base2(sobol(index, d), hash_combine(seed, d))) / float(0xffffffffu);
    }

    return xi;
}

